      const half = Math.PI / 2;
      const start = _DashLine.transform(x3 + radius, y3, matrix).clone();
      this.moveTo(start.x, start.y);
      let p3 = _DashLine.transform(x3 + width - radius, y3, matrix);
      this.lineTo(p3.x, p3.y);
      this.arcTo(x3 + width - radius, y3 + radius, radius, -half, 0, points, matrix);
      p3 = _DashLine.transform(x3 + width, y3 + height - radius, matrix);
      this.lineTo(p3.x, p3.y);
      this.arcTo(x3 + width - radius, y3 + height - radius, radius, 0, half, points, matrix);
      p3 = _DashLine.transform(x3 + radius, y3 + height, matrix);
      this.lineTo(p3.x, p3.y);
      this.arcTo(x3 + radius, y3 + height - radius, radius, half, Math.PI, points, matrix);
      p3 = _DashLine.transform(x3, y3 + radius, matrix);
      this.lineTo(p3.x, p3.y);
      this.arcTo(x3 + radius, y3 + radius, radius, Math.PI, Math.PI + half - half / points, points - 1, matrix);
